(()=>{
  const $=id=>document.getElementById(id);
  const esc=value=>String(value??"").replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[char]));
  const week1=[
    null,
    {day:1,title:"Why build a dam?",short:"Dam Builders",image:"assets/science-beaver-wetland-v1.png",icon:"🌊",reward:"Stream Map",rewardIcon:"🗺️",story:"A beaver's habitat needs water, food and shelter. In a shallow, fast stream, a beaver builds a dam from branches, stones and mud. The barrier slows the water. Water collects behind it and forms a deeper, calmer pond. The pond gives the beaver safer water and a place to build its home.",vi:"Môi trường sống của hải ly cần có nước, thức ăn và nơi trú ẩn. Ở một dòng suối nông, chảy nhanh, hải ly xây đập bằng cành cây, đá và bùn. Vật cản làm dòng nước chậm lại. Nước tích tụ phía sau và tạo thành một hồ sâu, yên hơn. Hồ nước mang lại vùng nước an toàn hơn và nơi để hải ly xây tổ.",words:[{en:"habitat",vi:"môi trường sống",meaning:"the natural home of a plant or animal"},{en:"dam",vi:"đập nước",meaning:"a barrier that stops or slows flowing water"},{en:"pond",vi:"hồ nhỏ",meaning:"a small body of still water"}],questions:[{prompt:"Why does a beaver build a dam across a shallow stream?",vi:"Vì sao hải ly xây đập ngang một dòng suối nông?",choices:["To form a deeper, calmer pond","To make the forest completely dry","To remove every plant"],right:0,why:"The dam slows the stream, so water collects and forms a pond.",hint1:"Think about the water behind the branches.",hint2:"A barrier makes flowing water slow down and collect."},{prompt:"What happens first when the dam blocks part of the stream?",vi:"Điều gì xảy ra đầu tiên khi con đập chặn một phần dòng suối?",choices:["The water slows down","The lodge flies away","The soil turns into rock"],right:0,why:"The branches and mud resist the current, so the water slows.",hint1:"Watch the moving water at the dam.",hint2:"The dam is a barrier in the current."}]},
    {day:2,title:"Inside a beaver lodge",short:"Secret Lodge",image:"assets/science-beaver-lodge-v1.png",icon:"🛖",reward:"Lodge Blueprint",rewardIcon:"📐",story:"A beaver's home is called a lodge. It is built from branches and mud, often in the pond created by the dam. The entrance is below the water, but the sleeping chamber is dry and above the water level. Thick walls help protect the beaver and keep the chamber warmer.",vi:"Nhà của hải ly được gọi là tổ hải ly. Tổ được xây bằng cành cây và bùn, thường nằm trong hồ do đập tạo ra. Lối vào nằm dưới mặt nước, nhưng khoang ngủ khô ráo và nằm cao hơn mực nước. Những bức tường dày giúp bảo vệ hải ly và giữ cho khoang bên trong ấm hơn.",words:[{en:"lodge",vi:"tổ hải ly",meaning:"a beaver's home made from branches and mud"},{en:"entrance",vi:"lối vào",meaning:"a way into a place"},{en:"chamber",vi:"khoang bên trong",meaning:"an enclosed space inside a structure"}],questions:[{prompt:"Why is the lodge entrance under the water?",vi:"Vì sao lối vào tổ hải ly nằm dưới nước?",choices:["It gives the beaver a protected route into its home","It lets sunlight heat the lodge","It helps trees grow inside"],right:0,why:"The beaver can swim inside while many land predators cannot easily follow.",hint1:"Which animals can follow a beaver underwater?",hint2:"The pond becomes a protective path to the lodge."},{prompt:"Which part of the lodge should stay dry?",vi:"Phần nào của tổ hải ly cần được giữ khô ráo?",choices:["The inner sleeping chamber","The underwater entrance","The pond floor"],right:0,why:"The entrance is underwater, but the inner chamber is above the water level.",hint1:"Look above the waterline in the cutaway.",hint2:"The beaver rests in the highest inner space."}]},
    {day:3,title:"Trees: food and winter store",short:"Winter Pantry",image:"assets/science-beaver-winter-food-v1.png",icon:"🌳",reward:"Winter Food Sample",rewardIcon:"🍃",story:"Trees provide both building material and food. Beavers eat bark, twigs and leaves from trees such as willow and aspen. Before winter, they collect branches and store them underwater near the lodge. When ice covers the pond, the beavers can swim to this food cache without walking far on land.",vi:"Cây vừa cung cấp vật liệu xây dựng vừa cung cấp thức ăn. Hải ly ăn vỏ cây, cành nhỏ và lá của những cây như liễu và dương. Trước mùa đông, chúng thu gom cành cây và dự trữ dưới nước gần tổ. Khi băng phủ mặt hồ, hải ly có thể bơi đến kho thức ăn này mà không phải đi xa trên cạn.",words:[{en:"bark",vi:"vỏ cây",meaning:"the protective outer covering of a tree"},{en:"twigs",vi:"cành nhỏ",meaning:"small, thin branches"},{en:"food cache",vi:"kho thức ăn",meaning:"food stored for later use"}],questions:[{prompt:"Why do beavers store branches underwater near their lodge?",vi:"Vì sao hải ly dự trữ cành cây dưới nước gần tổ?",choices:["To reach food safely during winter","To teach fish to climb trees","To make the pond disappear"],right:0,why:"The underwater cache keeps winter food close to the protected lodge.",hint1:"Think about what happens when ice covers the pond.",hint2:"The beaver can swim from the lodge to its stored food."},{prompt:"How can the same tree help a beaver in two ways?",vi:"Một cái cây có thể giúp hải ly theo hai cách như thế nào?",choices:["It provides food and building material","It makes both sunlight and snow","It turns water into soil"],right:0,why:"Beavers eat parts of trees and also use branches to build dams and lodges.",hint1:"Look at what the beaver carries and eats.",hint2:"Branches can be used, while bark, leaves and twigs can be eaten."}]},
    {day:4,title:"How dams change habitats",short:"Wetland Balance",image:"assets/science-wetland-effects-v1.png",icon:"🌿",reward:"Wetland Balance Data",rewardIcon:"⚖️",story:"A beaver dam changes more than the beaver's home. The new wetland can provide habitat for frogs, fish, ducks, insects and water plants. Slower water may reduce erosion, and fine soil called silt can settle to the bottom. However, rising water may flood nearby land, cover trails or change where some plants can grow. Scientists examine both benefits and costs.",vi:"Đập hải ly làm thay đổi nhiều thứ hơn là chỉ ngôi nhà của hải ly. Vùng đất ngập nước mới có thể tạo môi trường sống cho ếch, cá, vịt, côn trùng và thực vật thủy sinh. Nước chảy chậm hơn có thể làm giảm xói mòn, đồng thời đất mịn gọi là phù sa có thể lắng xuống đáy. Tuy nhiên, mực nước dâng có thể làm ngập vùng đất gần đó, che phủ đường mòn hoặc thay đổi nơi một số loài cây có thể phát triển. Các nhà khoa học xem xét cả lợi ích lẫn tác động bất lợi.",words:[{en:"wetland",vi:"vùng đất ngập nước",meaning:"land that stays covered or filled with water"},{en:"erosion",vi:"sự xói mòn",meaning:"the wearing away of soil by water or wind"},{en:"silt",vi:"phù sa",meaning:"fine soil carried and left behind by water"}],questions:[{prompt:"Which is a benefit of a beaver wetland?",vi:"Điều nào là một lợi ích của vùng đất ngập nước do hải ly tạo ra?",choices:["It creates habitat for many living things","It removes all water from the area","It prevents every kind of change"],right:0,why:"Wetlands provide water, food and shelter for many organisms.",hint1:"Look for the different animals in the pond.",hint2:"A habitat supplies what living things need."},{prompt:"Why can slower water reduce erosion?",vi:"Vì sao nước chảy chậm hơn có thể làm giảm xói mòn?",choices:["It has less force to carry soil away","It makes soil weightless","It stops gravity"],right:0,why:"Slower water pushes with less force, so it may carry away less soil.",hint1:"Compare a fast current with calm pond water.",hint2:"Less speed usually means less force on the bank."},{prompt:"What is one possible negative effect of a dam?",vi:"Một tác động bất lợi có thể xảy ra của con đập là gì?",choices:["Nearby low land may flood","All insects vanish immediately","The Sun becomes cooler"],right:0,why:"Water collecting behind the dam can spread over nearby low ground.",hint1:"Look at the trail on the right side of the scene.",hint2:"A higher water level can cover low places."}]},
    {day:5,title:"Beaver field report",short:"Week Review",image:"assets/science-earth-lab-v1.png",icon:"🔬",reward:"Wetland Core",rewardIcon:"💎",story:"Nilo is ready to send the week's field report. Use evidence from the stream, lodge, winter food cache and wetland to explain the whole system. A dam slows water and forms a pond. The pond protects an underwater lodge entrance, keeps stored food close and creates habitat for many living things. Every change can have both helpful and harmful effects.",vi:"Nilo đã sẵn sàng gửi báo cáo thực địa của tuần. Hãy dùng bằng chứng từ dòng suối, tổ hải ly, kho thức ăn mùa đông và vùng đất ngập nước để giải thích toàn bộ hệ thống. Con đập làm nước chảy chậm và tạo thành hồ. Hồ bảo vệ lối vào tổ dưới nước, giữ nguồn thức ăn dự trữ ở gần và tạo môi trường sống cho nhiều sinh vật. Mỗi thay đổi đều có thể mang lại cả tác động có lợi lẫn bất lợi.",words:[{en:"cause",vi:"nguyên nhân",meaning:"something that makes an event happen"},{en:"effect",vi:"kết quả, tác động",meaning:"a change that happens because of a cause"},{en:"evidence",vi:"bằng chứng",meaning:"information used to support an explanation"}],questions:[{prompt:"Complete the cause-and-effect chain: dam → slower water → ...",vi:"Hoàn thành chuỗi nguyên nhân–kết quả: đập → nước chảy chậm hơn → ...",choices:["a deeper pond forms","the stream jumps uphill","all soil disappears"],right:0,why:"Water collects behind the dam and forms a deeper pond.",hint1:"Remember Day 1.",hint2:"Slow water collects behind a barrier."},{prompt:"Which evidence best shows that the lodge is protected?",vi:"Bằng chứng nào cho thấy tổ hải ly được bảo vệ tốt nhất?",choices:["Its entrance is underwater","It has leaves nearby","The pond reflects the sky"],right:0,why:"The underwater entrance is hard for many land predators to reach.",hint1:"Remember the Day 2 cutaway.",hint2:"Focus on the route into the lodge."},{prompt:"Why is a food cache useful in winter?",vi:"Vì sao kho thức ăn hữu ích vào mùa đông?",choices:["Food stays close to the lodge under the water","It makes new sunlight","It teaches branches to grow"],right:0,why:"The beaver can swim to stored branches even when the pond surface freezes.",hint1:"Remember Day 3.",hint2:"Think about travel when the surface is icy."},{prompt:"Which pair shows one benefit and one cost of a dam?",vi:"Cặp nào cho thấy một lợi ích và một tác động bất lợi của con đập?",choices:["New wetland habitat; nearby low land may flood","More habitat; no environmental change","Less erosion; water stops existing"],right:0,why:"The wetland supports wildlife, but higher water can flood low ground.",hint1:"Remember the two sides of Day 4.",hint2:"Choose one helpful effect and one possible problem."},{prompt:"Which sentence is the best field-report conclusion?",vi:"Câu nào là kết luận phù hợp nhất cho báo cáo thực địa?",choices:["Beavers change streams to create habitat that helps them survive","Beavers build dams only to make noise","A dam has no effect on other living things"],right:0,why:"This conclusion connects the beaver's behavior, habitat and survival.",hint1:"Use evidence from all four days.",hint2:"The best conclusion explains both the action and its purpose."}]}
  ];
  const week2=[
    null,
    {day:1,title:"From flower to fruit",short:"Fruit Factory",image:"assets/science-flower-fruit-v1.png",icon:"🌸",reward:"Pollination Sequence",rewardIcon:"🧬",story:"A fruit begins as part of a flower. Pollen from the male part of a flower must reach the female cells in the flower's ovary. This process is called pollination. After pollination, seeds begin to form and the ovary grows larger around them. The enlarged ovary becomes a fruit that protects the developing seeds.",vi:"Một quả bắt đầu từ một phần của hoa. Phấn hoa từ bộ phận đực của hoa phải đến được các tế bào cái trong bầu nhụy. Quá trình này được gọi là sự thụ phấn. Sau khi thụ phấn, hạt bắt đầu hình thành và bầu nhụy lớn dần bao quanh chúng. Bầu nhụy phát triển thành quả, giúp bảo vệ những hạt đang lớn.",guide:"Mira",guideLine:"Follow the flower carefully—the fruit is already beginning inside it.",words:[{en:"ovary",vi:"bầu nhụy",meaning:"the part of a flower where seeds begin to form"},{en:"pollen",vi:"phấn hoa",meaning:"fine powder made by the male part of a flower"},{en:"pollination",vi:"sự thụ phấn",meaning:"the transfer of pollen that allows seeds to form"}],questions:[{prompt:"Which sequence correctly shows how many fruits begin?",vi:"Trình tự nào cho thấy đúng cách nhiều loại quả bắt đầu hình thành?",choices:["Flower blooms → pollination → seeds form → ovary becomes fruit","Fruit grows → flower appears → seeds disappear","Roots become pollen → leaves become fruit"],right:0,why:"Pollination happens in the flower; then seeds form and the ovary enlarges into fruit.",hint1:"Start with the open flower in Mira's picture.",hint2:"Pollen must reach the flower before seeds and fruit can develop."},{prompt:"Why is fruit useful to a flowering plant?",vi:"Quả có ích gì cho thực vật có hoa?",choices:["It surrounds and protects developing seeds","It replaces every root","It stops the plant from reproducing"],right:0,why:"Fruit develops around the seeds and helps protect them.",hint1:"Look inside the cut fruit.",hint2:"The seeds are surrounded by the enlarged ovary."}]},
    {day:2,title:"Meet the angiosperms",short:"Flower Network",image:"assets/science-angiosperm-pollination-v1.png",icon:"🐝",reward:"Angiosperm Scanner",rewardIcon:"🔎",story:"Flowering plants are called angiosperms. They make up most of the plant life we see on land. Their flowers attract bees, butterflies and other pollinators with color, scent or nectar. As an animal visits flowers, pollen can move from one flower to another. This helps the plants make seeds and fruit.",vi:"Thực vật có hoa được gọi là thực vật hạt kín. Chúng chiếm phần lớn các loài thực vật mà chúng ta nhìn thấy trên cạn. Hoa thu hút ong, bướm và các loài thụ phấn khác bằng màu sắc, mùi hương hoặc mật hoa. Khi động vật ghé thăm các bông hoa, phấn hoa có thể được chuyển từ hoa này sang hoa khác. Điều này giúp cây tạo hạt và quả.",guide:"Mira",guideLine:"A bright flower is more than decoration—it can be an invitation to a pollinator.",words:[{en:"angiosperm",vi:"thực vật hạt kín",meaning:"a plant that produces flowers and seeds inside fruit"},{en:"pollinator",vi:"động vật thụ phấn",meaning:"an animal that carries pollen between flowers"},{en:"nectar",vi:"mật hoa",meaning:"a sweet liquid in flowers that attracts animals"}],questions:[{prompt:"Which plant is an angiosperm?",vi:"Cây nào là thực vật hạt kín?",choices:["An apple tree with blossoms","A mushroom","A moss with no flowers"],right:0,why:"Apple trees produce flowers, so they are angiosperms.",hint1:"Look for a plant that makes flowers.",hint2:"Angiosperms produce flowers and fruit."},{prompt:"How can a bee help a plant make fruit?",vi:"Ong có thể giúp cây tạo quả bằng cách nào?",choices:["By carrying pollen between flowers","By cutting off every flower","By hiding all the seeds underground"],right:0,why:"Pollen carried between flowers can make pollination possible.",hint1:"Notice the yellow dust on the bee.",hint2:"The bee moves pollen as it visits different blossoms."}]},
    {day:3,title:"Seeds on the move",short:"Seed Travellers",image:"assets/science-seed-dispersal-v1.png",icon:"🐦",reward:"Seed Dispersal Map",rewardIcon:"🗺️",story:"Fruit can help seeds travel away from the parent plant. A bird or another animal may eat a fruit and carry its seeds to a new place. Some seeds are dropped with pieces of fruit. Others pass through an animal's digestive system unharmed and are left far away. People also move seeds, both on purpose and by accident.",vi:"Quả có thể giúp hạt di chuyển ra xa cây mẹ. Chim hoặc các động vật khác có thể ăn quả và mang hạt đến một nơi mới. Một số hạt rơi xuống cùng với những mẩu quả. Những hạt khác đi qua hệ tiêu hóa của động vật mà không bị hỏng rồi được thải ra ở nơi xa. Con người cũng di chuyển hạt, cả có chủ ý lẫn vô tình.",guide:"Mira",guideLine:"A fruit is also a travel capsule. Track where each seed lands.",words:[{en:"disperse",vi:"phát tán",meaning:"to spread or move in different directions"},{en:"digestive system",vi:"hệ tiêu hóa",meaning:"the organs that break down food inside an animal"},{en:"parent plant",vi:"cây mẹ",meaning:"the plant that produced the seeds"}],questions:[{prompt:"How can an animal help disperse seeds?",vi:"Động vật có thể giúp phát tán hạt bằng cách nào?",choices:["It carries or passes seeds to a different place","It turns every seed into a flower at once","It keeps every seed beside the parent plant"],right:0,why:"Animals can carry seeds away after eating or moving fruit.",hint1:"Follow the birds and the fox in the scene.",hint2:"The animal moves before the seed is dropped or passed."},{prompt:"Why can dispersal help a young plant?",vi:"Vì sao sự phát tán có thể giúp cây non?",choices:["It may reduce competition with the parent plant","It removes the need for water","It guarantees that every seed will grow"],right:0,why:"A seed farther away may have more space, light, water and nutrients.",hint1:"Imagine many seedlings growing under one tree.",hint2:"Plants close together compete for the same resources."}]},
    {day:4,title:"The mystery of seedless fruit",short:"Banana Mystery",image:"assets/science-seedless-fruit-v1.png",icon:"🍌",reward:"Mutation Sample",rewardIcon:"🧪",story:"Fruits normally develop to protect seeds, but some cultivated fruits are seedless. The first seedless fruits probably appeared because of a natural mutation—a change in a living thing. Today's common seedless bananas are sterile, so they cannot make working seeds. Farmers grow new banana plants from shoots that develop beside an older plant's roots.",vi:"Quả thường phát triển để bảo vệ hạt, nhưng một số loại quả được trồng lại không có hạt. Những quả không hạt đầu tiên có lẽ xuất hiện do đột biến tự nhiên—một sự thay đổi ở sinh vật sống. Những giống chuối không hạt phổ biến ngày nay là bất thụ nên không thể tạo ra hạt có khả năng phát triển. Nông dân trồng cây chuối mới từ các chồi mọc bên cạnh rễ của cây lớn.",guide:"Mira",guideLine:"No working seeds? Then look underground—the new plant starts beside the old one.",words:[{en:"mutation",vi:"đột biến",meaning:"a change in the traits or genetic material of a living thing"},{en:"sterile",vi:"bất thụ",meaning:"unable to produce working seeds or offspring"},{en:"shoot",vi:"chồi",meaning:"a young stem that grows from a plant"}],questions:[{prompt:"Why do farmers use shoots to grow common seedless bananas?",vi:"Vì sao nông dân dùng chồi để trồng các giống chuối không hạt phổ biến?",choices:["The plants are sterile and do not make working seeds","Shoots are a kind of animal","The fruit grows only in water"],right:0,why:"A shoot can become a new plant even when the banana has no working seeds.",hint1:"Look at the small plant beside the roots.",hint2:"Sterile plants cannot reproduce with working seeds."},{prompt:"What is a mutation?",vi:"Đột biến là gì?",choices:["A change in a living thing","A type of flower visitor","A method for measuring rain"],right:0,why:"A mutation is a change that can sometimes produce a new trait, such as seedlessness.",hint1:"The seedless trait was not planned at first.",hint2:"It is a biological change in a living thing."},{prompt:"What could happen to seedless bananas without people growing their shoots?",vi:"Điều gì có thể xảy ra với chuối không hạt nếu con người không trồng các chồi của chúng?",choices:["They could disappear because they cannot reproduce by seed","They would immediately grow hard seeds","They would turn into flowers forever"],right:0,why:"Sterile banana plants depend on people propagating their shoots.",hint1:"Ask how the next generation would begin.",hint2:"No working seeds means the shoots must be replanted."}]},
    {day:5,title:"Fruit and seed field report",short:"Week Review",image:"assets/science-flower-fruit-v1.png",icon:"🔬",reward:"Seed Voyager Core",rewardIcon:"💎",story:"Mira is ready to connect the week's evidence. Pollination allows seeds to begin forming in a flower's ovary. The ovary grows into fruit, which protects seeds. Flowers can recruit pollinators, while fruit can recruit animals that spread seeds. Even seedless cultivated fruits reveal how mutations and people can change the way plants reproduce.",vi:"Mira đã sẵn sàng kết nối bằng chứng của cả tuần. Sự thụ phấn cho phép hạt bắt đầu hình thành trong bầu nhụy của hoa. Bầu nhụy phát triển thành quả, giúp bảo vệ hạt. Hoa có thể thu hút động vật thụ phấn, còn quả có thể thu hút động vật giúp phát tán hạt. Ngay cả quả không hạt được trồng cũng cho thấy đột biến và con người có thể thay đổi cách thực vật sinh sản.",guide:"Mira",guideLine:"One system connects flowers, pollinators, fruit, animals and new plants.",words:[{en:"reproduce",vi:"sinh sản",meaning:"to make new living things of the same kind"},{en:"protect",vi:"bảo vệ",meaning:"to keep something safe from harm"},{en:"distribute",vi:"phân bố, phát tán",meaning:"to spread things among different places"}],questions:[{prompt:"What happens directly after successful pollination?",vi:"Điều gì xảy ra sau khi thụ phấn thành công?",choices:["Seeds begin to form and the ovary starts enlarging","The roots become fruit","Every petal becomes a seed"],right:0,why:"Pollination allows seeds to form, and the ovary develops around them.",hint1:"Remember Day 1's sequence.",hint2:"The change begins inside the flower's ovary."},{prompt:"Which living thing is acting as a pollinator?",vi:"Sinh vật nào đang đóng vai trò là động vật thụ phấn?",choices:["A bee carrying pollen between flowers","A fox carrying a berry","A farmer replanting a banana shoot"],right:0,why:"A pollinator transfers pollen between flowers.",hint1:"Remember Day 2.",hint2:"Look for an animal moving pollen, not seeds."},{prompt:"Which example shows seed dispersal?",vi:"Ví dụ nào cho thấy sự phát tán hạt?",choices:["A bird drops a berry seed far from the parent plant","A flower makes nectar","A banana shoot grows beside a root"],right:0,why:"The bird moves a seed to a new place away from the parent plant.",hint1:"Remember Day 3.",hint2:"Dispersal means spreading seeds to different places."},{prompt:"Why do people propagate seedless bananas from shoots?",vi:"Vì sao con người nhân giống chuối không hạt bằng chồi?",choices:["The plants are sterile","The shoots make pollen for bees","The fruit contains too much water"],right:0,why:"Sterile seedless bananas cannot make working seeds, so shoots are used.",hint1:"Remember Day 4.",hint2:"A sterile plant needs another way to produce new plants."},{prompt:"Which statement best answers: Why do some plants have fruit?",vi:"Câu nào trả lời tốt nhất cho câu hỏi: Vì sao một số loài cây có quả?",choices:["Fruit protects seeds and can help them reach new places","Fruit prevents plants from reproducing","Fruit is only decoration for flowers"],right:0,why:"Fruit surrounds seeds, and animals that eat it may disperse those seeds.",hint1:"Connect protection and travel.",hint2:"Use evidence from both the flower and the animals."}]}
  ];
  const week3=[
    null,
    {day:1,title:"Built for flowers",short:"Bee Tool Kit",image:"assets/science-bee-tools-v1.png",icon:"🐝",reward:"Bee Adaptation Scan",rewardIcon:"🔬",story:"A bee carries a remarkable tool kit on its body. Its long, tube-like proboscis reaches nectar deep inside a flower. Fine body hairs collect loose pollen, while brush-like hairs on the hind legs pack pollen into baskets. The bee gains food, and the flower receives pollen that may help it reproduce.",vi:"Cơ thể của ong mang theo một bộ công cụ đáng kinh ngạc. Chiếc vòi dài hình ống giúp ong hút mật nằm sâu trong hoa. Những sợi lông mịn trên cơ thể giữ lại phấn hoa, còn lông dạng bàn chải ở chân sau gom phấn thành những khối trong giỏ phấn. Ong nhận được thức ăn, đồng thời hoa nhận được phấn hoa có thể giúp cây sinh sản.",guide:"Kiko",guideLine:"Read the bee's body like a tool kit—each structure solves a different problem.",words:[{en:"nectar",vi:"mật hoa",meaning:"a sugary liquid made by flowers"},{en:"proboscis",vi:"vòi hút",meaning:"a long tube-like mouthpart used to drink liquids"},{en:"pollen basket",vi:"giỏ phấn",meaning:"an area on a bee's hind leg where packed pollen is carried"}],questions:[{prompt:"Which bee structure works most like a drinking straw?",vi:"Bộ phận nào của ong hoạt động giống ống hút nhất?",choices:["The proboscis","The wing","The antenna"],right:0,why:"The proboscis is a tube-like mouthpart that reaches liquid nectar.",hint1:"Look closely at the bee's mouth near the flower.",hint2:"Choose the long part used to draw up liquid."},{prompt:"How does a bee's fuzzy body help both the bee and the flower?",vi:"Cơ thể nhiều lông của ong giúp ích cho cả ong và hoa như thế nào?",choices:["It collects pollen for food and carries some pollen to other flowers","It turns pollen into water","It prevents the bee from visiting flowers"],right:0,why:"Pollen sticks to the hairs; the bee carries food and also transfers pollen between flowers.",hint1:"Think about what sticks to the bee's hairs.",hint2:"The same pollen can feed the hive and reach another flower."}]},
    {day:2,title:"From nectar to honey",short:"Honey Workshop",image:"assets/science-bee-honey-making-v1.png",icon:"🍯",reward:"Honey Process Record",rewardIcon:"🧪",story:"A worker honeybee carries nectar to the hive in a special storage sac often called a honey stomach. It places the nectar into wax honeycomb cells. Other workers fan their wings over the cells, helping water leave the nectar. As the nectar loses water, it becomes thicker and turns into honey that can feed the colony later.",vi:"Ong thợ mang mật hoa về tổ trong một túi chứa đặc biệt thường được gọi là dạ dày mật. Ong đưa mật hoa vào các ô sáp của tổ ong. Những ong thợ khác quạt cánh trên các ô, giúp nước thoát khỏi mật hoa. Khi mất bớt nước, mật hoa trở nên đặc hơn và biến thành mật ong để nuôi đàn ong sau này.",guide:"Kiko",guideLine:"Honey is not collected ready-made—the colony changes nectar step by step.",words:[{en:"honey stomach",vi:"dạ dày mật",meaning:"a storage sac a worker bee uses to carry nectar"},{en:"honeycomb",vi:"tổ ong dạng ô sáp",meaning:"a structure of six-sided wax cells used for food and young"},{en:"evaporate",vi:"bay hơi",meaning:"to change from liquid water into water vapor"}],questions:[{prompt:"Which sequence correctly shows how nectar becomes honey?",vi:"Trình tự nào mô tả đúng quá trình mật hoa trở thành mật ong?",choices:["Collect nectar → carry it to the hive → place it in honeycomb → fan away water","Build honeycomb → add soil → freeze the cells","Collect pollen → bury it underground → turn it into honey"],right:0,why:"Workers carry nectar home, store it in cells and fan it so water evaporates.",hint1:"Begin at the flower and end inside the hive.",hint2:"The liquid must lose water before it becomes thick honey."},{prompt:"Why do worker bees fan their wings over nectar-filled cells?",vi:"Vì sao ong thợ quạt cánh trên các ô chứa mật hoa?",choices:["To help water evaporate from the nectar","To make the wax colder than ice","To blow the honey out of the hive"],right:0,why:"Moving air speeds evaporation, so the nectar becomes more concentrated.",hint1:"Watch what happens to water in moving air.",hint2:"Less water makes the nectar thicker."}]},
    {day:3,title:"Honeybee or bumblebee?",short:"Bee Comparison",image:"assets/science-bee-compare-v1.png",icon:"🔎",reward:"Bee Species File",rewardIcon:"📋",story:"Not every bee produces a large store of honey. Honeybees live in large colonies and keep enough honey in combs to feed the colony through times when flowers are scarce. Bumblebees also drink nectar and pollinate flowers, but their colonies are smaller and usually do not store large amounts of honey for winter. Both kinds still depend on flowers.",vi:"Không phải loài ong nào cũng tạo ra một lượng mật lớn để dự trữ. Ong mật sống thành đàn lớn và giữ đủ mật trong tổ để nuôi đàn khi hoa khan hiếm. Ong nghệ cũng uống mật hoa và thụ phấn cho hoa, nhưng đàn của chúng nhỏ hơn và thường không dự trữ nhiều mật cho mùa đông. Cả hai loại ong vẫn phụ thuộc vào hoa.",guide:"Kiko",guideLine:"Do not judge by color alone—compare body shape, colony life and food storage.",words:[{en:"honeybee",vi:"ong mật",meaning:"a social bee that stores a large supply of honey"},{en:"bumblebee",vi:"ong nghệ",meaning:"a large fuzzy bee that pollinates flowers but stores little honey"},{en:"colony",vi:"đàn ong",meaning:"a group of bees living and working together"}],questions:[{prompt:"Which fact is true for both honeybees and bumblebees?",vi:"Thông tin nào đúng với cả ong mật và ong nghệ?",choices:["They visit flowers for nectar and can carry pollen","They both store huge amounts of winter honey","They both live alone all year"],right:0,why:"Both groups depend on flowers and act as pollinators, even though their colonies store food differently.",hint1:"Look for the behavior shared at flowers.",hint2:"Making a large honey store is not shared by both."},{prompt:"Why can the name honeybee be misleading when people talk about all bees?",vi:"Vì sao tên gọi ong mật có thể gây hiểu nhầm khi nói về tất cả các loài ong?",choices:["Many bee species do not make large stores of honey","No bee ever visits a flower","Only bumblebees carry pollen"],right:0,why:"Honeybees are one group; many other bees pollinate without producing abundant honey.",hint1:"Return to the week's main question.",hint2:"Compare the size of the honey stores, not whether bees visit flowers."}]},
    {day:4,title:"Bees at work in the orchard",short:"Orchard Partners",image:"assets/science-bee-orchard-pollination-v1.png",icon:"🌳",reward:"Orchard Pollination Map",rewardIcon:"🗺️",story:"Fruit growers need pollen to move between blossoms before many fruits can develop. During bloom, a beekeeper may place managed hives near an orchard. Foraging bees visit thousands of flowers and move pollen as they travel. This partnership gives bees nectar and pollen while helping farmers produce fruit.",vi:"Người trồng cây ăn quả cần phấn hoa được chuyển giữa các bông hoa trước khi nhiều loại quả có thể phát triển. Vào mùa hoa nở, người nuôi ong có thể đặt các tổ ong được quản lý gần vườn cây. Ong đi kiếm ăn ghé thăm hàng nghìn bông hoa và mang phấn hoa theo khi di chuyển. Mối quan hệ này cung cấp mật hoa và phấn hoa cho ong, đồng thời giúp nông dân tạo ra quả.",guide:"Kiko",guideLine:"Follow the path from hive to blossom to fruit—the farm is part of the system.",words:[{en:"pollination",vi:"sự thụ phấn",meaning:"the transfer of pollen that allows seeds and fruit to develop"},{en:"orchard",vi:"vườn cây ăn quả",meaning:"land where fruit trees are grown"},{en:"beekeeper",vi:"người nuôi ong",meaning:"a person who cares for managed bee colonies"}],questions:[{prompt:"Why might a farmer place beehives near an orchard during bloom?",vi:"Vì sao nông dân có thể đặt tổ ong gần vườn cây vào mùa hoa nở?",choices:["Bees can move pollen between blossoms","Bees can water every tree","The hives stop all insects from entering"],right:0,why:"More flower visits can increase successful pollination and fruit development.",hint1:"Think about what bees carry from flower to flower.",hint2:"Fruit begins only after the flower's reproductive process succeeds."},{prompt:"What do bees receive from their partnership with flowering crops?",vi:"Ong nhận được gì từ mối quan hệ với cây trồng có hoa?",choices:["Nectar and pollen for food","Wood for building dams","Fruit seeds for making wax"],right:0,why:"Flowers supply nectar and pollen, which bees use as food.",hint1:"Look at what the bee collects inside a blossom.",hint2:"The partnership must benefit the bee as well as the plant."},{prompt:"Why would a serious decline in pollinating bees concern fruit growers?",vi:"Vì sao sự suy giảm nghiêm trọng số lượng ong thụ phấn khiến người trồng cây ăn quả lo lắng?",choices:["Fewer flowers may be pollinated, so fewer fruits may develop","Every flower would immediately become honey","Trees would stop needing sunlight"],right:0,why:"Many fruit crops depend on animal pollinators to move pollen between flowers.",hint1:"Imagine the orchard with very few flower visitors.",hint2:"Connect pollination to the formation of seeds and fruit."}]},
    {day:5,title:"Bee partnership field report",short:"Week Review",image:"assets/science-bee-week-review-v1.png",icon:"🔬",reward:"Pollinator Network Core",rewardIcon:"💎",story:"Kiko is ready to connect the evidence. Bees have structures that help them collect nectar and pollen. Honeybees process nectar and store honey, while many other bees do not make large honey stores. All these bees can still pollinate flowers. The relationship between bees, flowering plants and farms shows how living things can depend on one another.",vi:"Kiko đã sẵn sàng kết nối các bằng chứng. Ong có những cấu tạo giúp chúng thu thập mật hoa và phấn hoa. Ong mật xử lý mật hoa rồi dự trữ mật ong, trong khi nhiều loài ong khác không tạo kho mật lớn. Tuy vậy, tất cả những loài ong này vẫn có thể thụ phấn cho hoa. Mối quan hệ giữa ong, thực vật có hoa và nông trại cho thấy các sinh vật có thể phụ thuộc lẫn nhau.",guide:"Kiko",guideLine:"A strong conclusion explains the whole network, not only the honey.",words:[{en:"interdependence",vi:"sự phụ thuộc lẫn nhau",meaning:"a relationship in which living things depend on one another"},{en:"evidence",vi:"bằng chứng",meaning:"observations or information used to support an explanation"},{en:"conclusion",vi:"kết luận",meaning:"an explanation reached after considering the evidence"}],questions:[{prompt:"Which adaptation helps a bee reach nectar deep inside a flower?",vi:"Đặc điểm thích nghi nào giúp ong lấy mật nằm sâu trong hoa?",choices:["A long proboscis","A wax cell","A broad tree leaf"],right:0,why:"The tube-like proboscis can reach liquid inside the flower.",hint1:"Recall Day 1's bee tool kit.",hint2:"Choose the mouthpart used like a straw."},{prompt:"What must happen for nectar to become thick honey?",vi:"Điều gì phải xảy ra để mật hoa trở thành mật ong đặc?",choices:["Much of its water must evaporate","It must be mixed with soil","It must freeze inside the flower"],right:0,why:"Workers fan the cells so water leaves the nectar.",hint1:"Recall the wing-fanning workers from Day 2.",hint2:"Honey is more concentrated than watery nectar."},{prompt:"Which statement correctly compares honeybees and bumblebees?",vi:"Câu nào so sánh đúng ong mật và ong nghệ?",choices:["Both pollinate, but honeybees store much more honey","Only bumblebees visit flowers","Both always keep the same colony size"],right:0,why:"Both use flowers, but their colony size and honey storage differ.",hint1:"Recall Day 3's side-by-side comparison.",hint2:"Separate pollination from large-scale honey storage."},{prompt:"Which observation is the best evidence that bees help an orchard reproduce?",vi:"Quan sát nào là bằng chứng tốt nhất cho thấy ong giúp vườn cây sinh sản?",choices:["Bees carry pollen between blossoms before fruit develops","Bees rest on the hive roof","Bees have striped bodies"],right:0,why:"Moving pollen between flowers directly supports fertilization and fruit development.",hint1:"Choose evidence connected to the plant's reproductive process.",hint2:"Color and resting behavior do not move pollen between blossoms."},{prompt:"What is the best answer to the weekly question: Do all bees make honey?",vi:"Câu trả lời phù hợp nhất cho câu hỏi của tuần: Có phải tất cả loài ong đều làm mật không?",choices:["No. Honeybees store abundant honey, while many other bees do not, although they can still pollinate","Yes. Every bee species fills large honeycombs","No. Bees use only pollen and never nectar"],right:0,why:"Honey production varies among bee groups, but flower visits and pollination are much more widespread.",hint1:"Use evidence from the honeybee and bumblebee comparison.",hint2:"The best conclusion answers both the honey question and the shared role of bees."}]}
  ];
  const week4=[
    null,
    {day:1,title:"A pantry for the cold",short:"Winter Hoard",image:"assets/science-winter-hoard-v1.png",icon:"🌰",reward:"Hoarding Route Map",rewardIcon:"🗺️",story:"Winter brings shorter days, colder temperatures and less available food. Some animals prepare by hoarding food in autumn. Squirrels hide acorns in trees or underground, blue jays and woodpeckers store nuts and seeds, and beavers stash branches underwater near their lodges. A useful hoard must stay safe and remain reachable when winter arrives.",vi:"Mùa đông có ngày ngắn hơn, nhiệt độ thấp hơn và nguồn thức ăn khan hiếm hơn. Một số động vật chuẩn bị bằng cách tích trữ thức ăn vào mùa thu. Sóc giấu quả sồi trên cây hoặc dưới đất, chim giẻ cùi xanh và chim gõ kiến cất giữ hạt, còn hải ly giấu cành cây dưới nước gần tổ. Một kho dự trữ hữu ích phải được giữ an toàn và vẫn có thể tiếp cận khi mùa đông đến.",guide:"Tova",guideLine:"Trace each food item from autumn collection to its winter hiding place.",words:[{en:"hoard",vi:"tích trữ",meaning:"to gather and store food or other things for later"},{en:"food shortage",vi:"sự thiếu thức ăn",meaning:"a time when less food is available than is needed"},{en:"stash",vi:"cất giấu",meaning:"to hide something in a safe place for future use"}],questions:[{prompt:"Why does a squirrel hoard acorns in autumn?",vi:"Vì sao sóc tích trữ quả sồi vào mùa thu?",choices:["Food will be harder to find in winter","Acorns make winter warmer","The squirrel cannot eat in autumn"],right:0,why:"Stored acorns remain available when plants produce less food in winter.",hint1:"Compare the amount of food in autumn and winter.",hint2:"A hoard is saved for a later shortage."},{prompt:"Which food is a bird most likely to hoard successfully?",vi:"Loại thức ăn nào chim có khả năng tích trữ thành công nhất?",choices:["Dry sunflower seeds","Live earthworms on the ground","Melting snow"],right:0,why:"Dry seeds can be hidden and remain usable longer than live worms.",hint1:"Choose something that can stay in a hiding place.",hint2:"Seeds store better than moving animals or water."},{prompt:"Why do beavers stash branches underwater near their lodges?",vi:"Vì sao hải ly cất cành cây dưới nước gần tổ?",choices:["They can reach the food safely when the pond freezes","The branches turn into fish","The branches make sunlight"],right:0,why:"The underwater food pile stays close to the lodge and can be reached beneath the ice.",hint1:"Think about the safest winter route from the lodge.",hint2:"Beavers can swim under ice to stored branches."}]},
    {day:2,title:"Energy stored in the body",short:"Fat Fuel",image:"assets/science-winter-fat-energy-v1.png",icon:"⚡",reward:"Body Energy Scan",rewardIcon:"🔬",story:"Many animals eat extra food during warm months. Their bodies store unused energy as fat. When winter food is scarce, the body can absorb this fat and release energy. Beavers store much of their fat in their tails. Queen bumblebees drink nectar before winter, and bears build large fat reserves during summer and fall. The stored fat is fuel, not a hidden meal outside the body.",vi:"Nhiều động vật ăn thêm thức ăn trong những tháng ấm. Cơ thể chúng dự trữ phần năng lượng chưa dùng dưới dạng mỡ. Khi thức ăn khan hiếm vào mùa đông, cơ thể có thể hấp thụ lượng mỡ này và giải phóng năng lượng. Hải ly dự trữ nhiều mỡ ở đuôi. Ong nghệ chúa uống mật hoa trước mùa đông, còn gấu tạo lượng mỡ dự trữ lớn trong mùa hè và mùa thu. Mỡ dự trữ là nhiên liệu bên trong cơ thể, không phải một bữa ăn được giấu bên ngoài.",guide:"Tova",guideLine:"Follow the energy: food enters the body, becomes stored fat, then powers winter survival.",words:[{en:"body fat",vi:"mỡ cơ thể",meaning:"stored energy held in an animal's body"},{en:"absorb",vi:"hấp thụ",meaning:"to take in and use a substance or energy"},{en:"energy",vi:"năng lượng",meaning:"the ability to move, grow and keep body systems working"}],questions:[{prompt:"What happens to extra food energy that an animal does not use immediately?",vi:"Điều gì xảy ra với năng lượng từ thức ăn dư thừa mà động vật chưa sử dụng ngay?",choices:["It may be stored as body fat","It always becomes fur","It disappears without changing"],right:0,why:"The body converts unused food energy into fat that can be used later.",hint1:"Look at the middle step in Tova's energy pathway.",hint2:"The body saves unused energy in a stored form."},{prompt:"Why is body fat useful when winter food is scarce?",vi:"Vì sao mỡ cơ thể hữu ích khi thức ăn mùa đông khan hiếm?",choices:["The body can use it to provide energy","It makes new plants grow instantly","It replaces the animal's shelter"],right:0,why:"Stored fat provides energy when the animal cannot find enough food.",hint1:"Ask what keeps body systems working.",hint2:"Fat acts like fuel stored inside the animal."},{prompt:"Which statement is supported by the evidence?",vi:"Nhận định nào được bằng chứng ủng hộ?",choices:["Different animals can store fat in different parts or amounts","Every animal stores all fat in its tail","Body fat is useful only in summer"],right:0,why:"Beavers, bumblebee queens and bears prepare differently, but all can store energy as fat.",hint1:"Compare the three animals in the field image.",hint2:"Do not assume every animal stores fat exactly like a beaver."}]},
    {day:3,title:"Dormancy and true hibernation",short:"Slow Down Lab",image:"assets/science-winter-dormancy-v1.png",icon:"🦇",reward:"Winter Metabolism Record",rewardIcon:"📋",story:"Some animals survive winter by becoming dormant and conserving energy. A dormant chipmunk stays still for long periods but may wake to eat food stored in its den. True hibernation is a much deeper form of dormancy. A hibernating bat's body temperature drops greatly, and its breathing and heart rate slow dramatically. Bears enter a deep winter sleep, but their temperature drops only a few degrees, so scientists distinguish this from true hibernation.",vi:"Một số động vật sống qua mùa đông bằng cách bước vào trạng thái bất hoạt và tiết kiệm năng lượng. Sóc chuột bất hoạt trong thời gian dài nhưng đôi lúc có thể thức dậy để ăn thức ăn dự trữ trong hang. Ngủ đông thực sự là một dạng bất hoạt sâu hơn nhiều. Nhiệt độ cơ thể của dơi ngủ đông giảm mạnh, nhịp thở và nhịp tim cũng chậm đi đáng kể. Gấu bước vào giấc ngủ sâu mùa đông, nhưng nhiệt độ chỉ giảm vài độ, vì vậy các nhà khoa học phân biệt trạng thái này với ngủ đông thực sự.",guide:"Tova",guideLine:"Do not judge by closed eyes—compare temperature, heart rate and ability to wake.",words:[{en:"dormant",vi:"bất hoạt",meaning:"inactive for a period in order to save energy"},{en:"hibernation",vi:"sự ngủ đông",meaning:"a deep dormant state in which body processes slow dramatically"},{en:"conserve",vi:"tiết kiệm",meaning:"to use less of something so it lasts longer"}],questions:[{prompt:"Which clue best identifies true hibernation?",vi:"Dấu hiệu nào xác định rõ nhất trạng thái ngủ đông thực sự?",choices:["Body temperature and heart rate drop dramatically","The animal closes its eyes for one night","The animal stores nuts in a tree"],right:0,why:"True hibernation includes major changes in temperature and other body processes.",hint1:"Look beyond whether the animal appears asleep.",hint2:"Measure what happens inside the body."},{prompt:"How does a dormant chipmunk differ from a truly hibernating bat?",vi:"Sóc chuột bất hoạt khác dơi ngủ đông thực sự như thế nào?",choices:["It may wake occasionally to eat stored food","Its body temperature always drops near the surroundings","It migrates thousands of miles"],right:0,why:"Dormant chipmunks can become active at times, while true hibernators are difficult to wake.",hint1:"Recall the food stored inside the chipmunk's den.",hint2:"One animal sometimes wakes during winter."},{prompt:"Why does slowing body processes help an animal survive winter?",vi:"Vì sao làm chậm các hoạt động của cơ thể giúp động vật sống qua mùa đông?",choices:["The animal uses less energy when food is limited","The animal produces unlimited food","The winter becomes shorter"],right:0,why:"A slower metabolism reduces the energy the animal must obtain from food.",hint1:"Connect stillness to energy use.",hint2:"Using less energy makes stored fuel last longer."}]},
    {day:4,title:"Following food to warmer places",short:"Migration Paths",image:"assets/science-winter-migration-v1.png",icon:"🧭",reward:"Migration Route Atlas",rewardIcon:"🗺️",story:"Animals that cannot store enough food or fat may migrate to places where food and open water are more plentiful. Ducks and snow geese fly south from summer feeding grounds. Arctic caribou travel hundreds of miles to find plants. Monarch butterflies fly from Canada and the northern United States to spend winter in Mexico. Predators may follow migrating prey, so one animal's movement can reshape an entire food relationship.",vi:"Những động vật không thể tích trữ đủ thức ăn hoặc mỡ có thể di cư đến nơi có nhiều thức ăn và nước không đóng băng hơn. Vịt và ngỗng tuyết bay về phía nam từ vùng kiếm ăn mùa hè. Tuần lộc Bắc Cực di chuyển hàng trăm dặm để tìm thực vật. Bướm vua bay từ Canada và miền bắc Hoa Kỳ đến Mexico để trú đông. Động vật săn mồi có thể đi theo con mồi di cư, vì vậy sự di chuyển của một loài có thể làm thay đổi cả mối quan hệ thức ăn.",guide:"Tova",guideLine:"Migration is not wandering—map the resource the animals are following.",words:[{en:"migrate",vi:"di cư",meaning:"to move to another location in search of food or shelter"},{en:"feeding grounds",vi:"vùng kiếm ăn",meaning:"an area where animals regularly find and eat food"},{en:"plentiful",vi:"dồi dào",meaning:"available in a large amount"}],questions:[{prompt:"Why do many animals migrate to warmer places in winter?",vi:"Vì sao nhiều động vật di cư đến những nơi ấm hơn vào mùa đông?",choices:["Food and unfrozen water may be more plentiful there","Warm places have no other animals","Migration makes them invisible"],right:0,why:"Warmer regions can still have growing plants, prey and liquid water.",hint1:"Compare a frozen pond with open water.",hint2:"Animals follow resources needed for survival."},{prompt:"A gray wolf preys on caribou. What may the wolf do when the herd migrates?",vi:"Sói xám săn tuần lộc. Sói có thể làm gì khi đàn tuần lộc di cư?",choices:["Follow the herd to continue finding prey","Begin eating sunlight","Stay behind because food becomes more plentiful"],right:0,why:"Predators often move with prey when that prey is an important food source.",hint1:"Follow the food chain, not only the map.",hint2:"If the prey leaves, the predator may need to move too."},{prompt:"Which example shows migration rather than hoarding?",vi:"Ví dụ nào thể hiện sự di cư thay vì tích trữ?",choices:["Monarch butterflies fly to Mexico for winter","A squirrel hides acorns underground","A beaver stores branches near its lodge"],right:0,why:"Migration means moving to another region; hoarding means storing items for later.",hint1:"Look for a long journey between locations.",hint2:"Hiding food does not move the whole animal population."}]},
    {day:5,title:"Winter survival field report",short:"Week Review",image:"assets/science-winter-review-v1.png",icon:"🔬",reward:"Winter Survival Core",rewardIcon:"💎",story:"Tova's field team has found four major winter strategies. Animals can hoard food outside the body, store energy as body fat, reduce energy use through dormancy or hibernation, or migrate toward plentiful resources. Each strategy connects an animal's behavior and body to its environment. Survival does not depend on one universal solution; it depends on matching a strategy to the animal's needs and habitat.",vi:"Đội khảo sát của Tova đã tìm thấy bốn chiến lược lớn để sống qua mùa đông. Động vật có thể tích trữ thức ăn bên ngoài cơ thể, dự trữ năng lượng dưới dạng mỡ, giảm mức sử dụng năng lượng bằng trạng thái bất hoạt hoặc ngủ đông, hoặc di cư đến nơi có nguồn tài nguyên dồi dào. Mỗi chiến lược kết nối hành vi và cơ thể của động vật với môi trường. Sự sống sót không phụ thuộc vào một giải pháp chung duy nhất mà phụ thuộc vào chiến lược phù hợp với nhu cầu và môi trường sống của từng loài.",guide:"Tova",guideLine:"Build the final explanation by matching each animal with its evidence and strategy.",words:[{en:"survival",vi:"sự sống sót",meaning:"the ability to stay alive through difficult conditions"},{en:"adaptation",vi:"đặc điểm thích nghi",meaning:"a body feature or behavior that helps a living thing survive"},{en:"evidence",vi:"bằng chứng",meaning:"observations or information used to support an explanation"}],questions:[{prompt:"Which pair correctly matches an animal with its winter strategy?",vi:"Cặp nào ghép đúng động vật với chiến lược mùa đông?",choices:["Squirrel — hoard acorns","Snow goose — hibernate underground","Bat — migrate by storing branches"],right:0,why:"Squirrels gather and hide acorns that they eat later in winter.",hint1:"Recall the autumn sequence from Day 1.",hint2:"A hoard is a stored supply outside the body."},{prompt:"What is the main difference between stored food and stored body fat?",vi:"Sự khác biệt chính giữa thức ăn dự trữ và mỡ cơ thể dự trữ là gì?",choices:["Stored food is kept outside the body; fat stores energy inside it","Only stored food can provide energy","Body fat is hidden in trees"],right:0,why:"Both help later, but the storage location and form are different.",hint1:"Compare a squirrel's acorn cache with a bear's body.",hint2:"One supply is retrieved and eaten; the other is already inside the animal."},{prompt:"Which evidence best supports that a bat is truly hibernating?",vi:"Bằng chứng nào ủng hộ tốt nhất rằng một con dơi đang ngủ đông thực sự?",choices:["Its body temperature and heart rate fall greatly","It is quiet for one afternoon","It collected seeds in autumn"],right:0,why:"Large changes in body processes distinguish true hibernation from ordinary rest.",hint1:"Use the measurements from Day 3.",hint2:"Closed eyes alone are not enough evidence."},{prompt:"Why may a predator migrate when its prey migrates?",vi:"Vì sao động vật săn mồi có thể di cư khi con mồi di cư?",choices:["Its food source has moved to a new place","Migration turns the predator into prey","Cold weather removes its need for food"],right:0,why:"Predator and prey movements are connected through the food relationship.",hint1:"Think about the gray wolf and caribou.",hint2:"Track where the predator's food goes."},{prompt:"What is the best answer to the weekly question: Where do animals get food in the winter?",vi:"Câu trả lời phù hợp nhất cho câu hỏi tuần: Động vật lấy thức ăn ở đâu vào mùa đông?",choices:["They use stored food or fat, reduce energy needs, or move to places with more food","Every animal finds fresh fruit under snow","All animals use exactly the same strategy"],right:0,why:"Animals use several strategies depending on their bodies, behavior and environment.",hint1:"Combine evidence from all four investigation days.",hint2:"The best conclusion includes more than one survival strategy."}]}
  ];
  const weeks={1:{number:1,title:"Why do beavers build dams?",subtitle:"Living Habitat Expedition",guide:"Nilo",hero:"assets/science-beaver-wetland-v1.png",days:week1,overview:["Habitat → dam → pond","Lodge structure and safety","Food and winter preparation","Environmental benefits and costs","Evidence-based field report"]},2:{number:2,title:"Why do some plants have fruit?",subtitle:"Fruit & Seed Network",guide:"Mira",hero:"assets/science-flower-fruit-v1.png",days:week2,overview:["Flower → pollination → fruit","Angiosperms and pollinators","Animals disperse seeds","Mutations and seedless fruit","Fruit-and-seed field report"]},3:{number:3,title:"Do all bees make honey?",subtitle:"Bee & Flower Partnership",guide:"Kiko",hero:"assets/science-bee-tools-v1.png",days:week3,overview:["Bee body adaptations","Nectar → evaporation → honey","Honeybees and bumblebees","Pollination in orchards","Interdependence field report"]},4:{number:4,title:"Where do animals get food in the winter?",subtitle:"Winter Survival Expedition",guide:"Tova",hero:"assets/science-winter-hoard-v1.png",days:week4,overview:["Food shortage and hoarding","Body fat stores energy","Dormancy and hibernation","Migration follows resources","Winter survival field report"]}};
  const realisticLessonImages={1:[null,"assets/science-beaver-wetland-v2.png","assets/science-beaver-lodge-v2.png","assets/science-beaver-winter-food-v2.png","assets/science-wetland-effects-v2.png","assets/science-beaver-field-report-v2.png"],2:[null,"assets/science-flower-fruit-v2.png","assets/science-angiosperm-pollination-v2.png","assets/science-seed-dispersal-v2.png","assets/science-seedless-fruit-v2.png","assets/science-fruit-week-review-v2.png"],3:[null,"assets/science-bee-tools-v1.png","assets/science-bee-honey-making-v1.png","assets/science-bee-compare-v1.png","assets/science-bee-orchard-pollination-v1.png","assets/science-bee-week-review-v1.png"],4:[null,"assets/science-winter-hoard-v1.png","assets/science-winter-fat-energy-v1.png","assets/science-winter-dormancy-v1.png","assets/science-winter-migration-v1.png","assets/science-winter-review-v1.png"]};
  const vocabularySheets={1:[null,"assets/science-vocab-w1d1-v1.png","assets/science-vocab-w1d2-v1.png","assets/science-vocab-w1d3-v1.png","assets/science-vocab-w1d4-v1.png","assets/science-vocab-w1d5-v1.png"],2:[null,"assets/science-vocab-w2d1-v1.png","assets/science-vocab-w2d2-v1.png","assets/science-vocab-w2d3-v1.png","assets/science-vocab-w2d4-v1.png","assets/science-vocab-w2d5-v1.png"],3:[null,"assets/science-vocab-w3d1-v1.png","assets/science-vocab-w3d2-v1.png","assets/science-vocab-w3d3-v1.png","assets/science-vocab-w3d4-v1.png","assets/science-vocab-w3d5-v1.png"],4:[null,"assets/science-vocab-w4d1-v1.png","assets/science-vocab-w4d2-v1.png","assets/science-vocab-w4d3-v1.png","assets/science-vocab-w4d4-v1.png","assets/science-vocab-w4d5-v1.png"]};
  Object.values(weeks).forEach(w=>w.days.slice(1).forEach(day=>{day.image=realisticLessonImages[w.number][day.day];day.vocabImage=vocabularySheets[w.number][day.day]}));
  Object.values(weeks).forEach(w=>w.hero=realisticLessonImages[w.number][1]);
  let ctx;
  function s(){return ctx.state.science}
  function normalizeState(){const defaults={view:"lab",currentWeek:1,currentDay:1,stage:0,questionIndex:0,cardsSeen:[],translated:[],answers:{},feedback:"",hintDepth:0,hiddenFound:false,completedDays:[],completedByWeek:null,labLevel:0,crystals:0,discoveries:[],vocabularyNotes:[]};Object.entries(defaults).forEach(([k,v])=>{if(s()[k]===undefined)s()[k]=v});if(!s().completedByWeek)s().completedByWeek={1:[...s().completedDays]};Object.keys(weeks).forEach(weekNo=>{if(!Array.isArray(s().completedByWeek[weekNo]))s().completedByWeek[weekNo]=[]});if(s().completed&&s().completedByWeek[1].length===0)s().completedByWeek[1]=[1];s().completedDays=s().completedByWeek[1];s().labLevel=doneTotal();s().crystals=doneTotal()}
  function persist(){normalizeState();ctx.save();ctx.updateHud()}
  function activeWeek(){return weeks[s().currentWeek]||weeks[1]}
  function current(){return activeWeek().days[s().currentDay]||activeWeek().days[1]}
  function doneDays(weekNo=s().currentWeek){return s().completedByWeek?.[weekNo]||[]}
  function doneTotal(){return Object.values(s().completedByWeek||{}).reduce((sum,days)=>sum+(Array.isArray(days)?days.length:0),0)}
  function key(stage=s().stage){return`${s().currentWeek}-${s().currentDay}-${stage}`}
  function cardKey(index){return`${s().currentWeek}-${s().currentDay}-${index}`}
  function answerKey(index=s().questionIndex){return`${s().currentWeek}-${s().currentDay}-${index}`}
  function go(view,stage){s().view=view;if(stage!==undefined)s().stage=stage;s().feedback="";s().hintDepth=0;persist();render()}
  function translated(){return s().translated.includes(key())}
  function translateButton(){const seen=translated(),locked=ctx.state.human.shield<1&&!seen;return `<button class="science-translate" id="scienceTranslate" ${locked||seen?"disabled":""}>${seen?"✓ Vietnamese shown":locked?"🔒 Translate · Need 1 Shield":"Translate · −1 Shield"}</button>`}
  function bindTranslate(){const button=$("scienceTranslate");if(!button)return;button.onclick=()=>{if(!translated()&&ctx.state.human.shield>0){ctx.state.human.shield--;s().translated.push(key());persist();render()}}}
  function vi(text){return translated()?`<p class="science-vi" lang="vi">${esc(text)}</p>`:""}
  function nextDay(weekNo=s().currentWeek){return[1,2,3,4,5].find(day=>!doneDays(weekNo).includes(day))||5}
  function dayStatus(day){return doneDays().includes(day)?"complete":day===nextDay()?"next":"open"}
  function renderLab(){const total=doneTotal(),totalDays=Object.keys(weeks).length*5;ctx.view.innerHTML=`<section class="science-lab-screen research-index"><button class="science-earth-back" id="scienceEarthBack">← Planet Earth</button><div class="science-lab-hero research-hero"><div class="science-lab-copy"><p class="science-kicker">EARTH DISCOVERY LAB</p><h1>Choose your<br><span>research path</span></h1><p>Each week is a self-contained 5-day expedition with a different guide, story, vocabulary kit and hidden research object.</p><div class="science-lab-stats"><span>🔬 Lab level <b>${total}/${totalDays}</b></span><span>💎 Knowledge crystals <b>${s().crystals}</b></span><span>✓ Days complete <b>${total}/${totalDays}</b></span></div></div></div><div class="science-week-heading"><div><p class="science-kicker">AVAILABLE EARTH RESEARCH</p><h2>${Object.keys(weeks).length} worlds · choose any expedition</h2></div><span>Progress is saved separately</span></div><div class="science-week-selector">${Object.values(weeks).map(w=>{const done=doneDays(w.number).length;return `<article class="science-week-card ${done===5?"complete":""}" style="--week-image:url('${w.hero}')"><div class="week-card-art"></div><div class="week-card-copy"><p class="science-kicker">WEEK ${w.number} · GUIDE ${w.guide.toUpperCase()}</p><h2>${esc(w.title)}</h2><p>${esc(w.subtitle)} · Five connected 5–7 minute missions.</p><div class="week-card-progress"><span><i style="width:${done*20}%"></i></span><b>${done}/5 complete</b></div><button data-week="${w.number}">${done?"Continue research":"Start research"} →</button></div></article>`}).join("")}</div></section>`;$("scienceEarthBack").onclick=ctx.openEarth;document.querySelectorAll("[data-week]").forEach(button=>button.onclick=()=>{s().currentWeek=Number(button.dataset.week);go("week")})}
  function renderWeek(){const w=activeWeek(),done=doneDays().length,totalDays=Object.keys(weeks).length*5;ctx.view.innerHTML=`<section class="science-lab-screen"><button class="science-earth-back" id="scienceLabBack">← Earth Research</button><div class="science-lab-hero week-hero" style="--week-hero:url('${w.hero}')"><div class="science-lab-copy"><p class="science-kicker">EARTH DISCOVERY LAB · WEEK ${w.number} · GUIDE ${w.guide.toUpperCase()}</p><h1>${esc(w.title)}</h1><p>${esc(w.subtitle)}. Preview any day or follow the recommended order.</p><div class="science-lab-stats"><span>🔬 Lab level <b>${doneTotal()}/${totalDays}</b></span><span>💎 Knowledge crystals <b>${s().crystals}</b></span><span>✓ Week progress <b>${done}/5</b></span></div></div></div><div class="science-week-heading"><div><p class="science-kicker">WEEK ${w.number} FIELD PLAN</p><h2>Five days · one connected story</h2></div><span>${done===5?"Week complete!":"Recommended: Day "+nextDay()}</span></div><div class="science-day-map">${w.days.slice(1).map(day=>{const status=dayStatus(day.day);return `<article class="science-day-card ${status}" style="--day-image:url('${day.image}')"><div class="day-number"><b>DAY ${day.day}</b><span>${status==="complete"?"✓ Complete":status==="next"?"Next mission":"Open"}</span></div><div class="day-card-copy"><i>${day.icon}</i><h3>${day.short}</h3><p>${day.title}</p><small>⏱ 5–7 min · ${day.words.length} words · ${day.questions.length} questions</small><button data-day="${day.day}">${status==="complete"?"Review day":"Start day"} →</button></div></article>`}).join("")}</div><section class="week-overview"><h2>What students build across the week</h2><div>${w.overview.map((item,index)=>`<span><b>Day ${index+1}</b>${esc(item)}</span>`).join("")}</div></section></section>`;$("scienceLabBack").onclick=()=>go("lab");document.querySelectorAll("[data-day]").forEach(button=>button.onclick=()=>startDay(Number(button.dataset.day)))}
  function randomizeChoices(day){day.questions.forEach(q=>{if(!q.originalChoices){q.originalChoices=[...q.choices];q.originalRight=q.right}const items=q.originalChoices.map((choice,index)=>({choice,correct:index===q.originalRight}));for(let i=items.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[items[i],items[j]]=[items[j],items[i]]}q.choices=items.map(item=>item.choice);q.right=items.findIndex(item=>item.correct)})}
  function startDay(day){s().currentDay=day;s().stage=0;s().questionIndex=0;s().feedback="";s().hintDepth=0;s().hiddenFound=false;s().cardsSeen=s().cardsSeen.filter(item=>!String(item).startsWith(`${s().currentWeek}-${day}-`));Object.keys(s().answers).filter(item=>item.startsWith(`${s().currentWeek}-${day}-`)).forEach(item=>delete s().answers[item]);randomizeChoices(current());go("lesson",0)}
  function lessonShell(body,actions=""){const day=current(),w=activeWeek(),max=day.day===5?5:4,index=s().stage+1,canTranslate=s().stage<max-1;ctx.view.innerHTML=`<section class="science-lesson-screen"><div class="science-progress"><button id="scienceBack">← Week ${w.number}</button><b>WEEK ${w.number} · DAY ${day.day}</b><div><span style="--science-progress:${Math.round(index/max*100)}%"></span></div><strong>${index}/${max}</strong></div><article class="science-lesson-card">${body}<div class="science-actions">${canTranslate?translateButton():""}${actions}</div></article></section>`;$("scienceBack").onclick=()=>go("week");bindTranslate()}
  function nextButton(label="Continue →"){return `<button class="science-primary" id="scienceNext">${label}</button>`}
  function renderStory(){const day=current(),guide=day.guide||"Nilo",line=day.guideLine||["First, follow the water.","A safe home has a clever entrance.","The same tree can solve more than one problem.","Scientists check benefits and costs.","Now connect every clue into one explanation."][day.day-1];lessonShell(`<div class="science-story-grid"><img src="${day.image}" alt="Day ${day.day}: ${esc(day.title)}"><div><p class="science-kicker">${guide.toUpperCase()}'S FIELD LOG · DAY ${day.day}</p><h1>${esc(day.title)}</h1><p class="science-lead">${esc(day.story)}</p>${vi(day.vi)}<div class="nilo-message"><span>👽</span><p><strong>${guide}:</strong> “${esc(line)}”</p></div></div></div>`,nextButton("Open field kit →"));$("scienceNext").onclick=()=>go("lesson",1)}
  function renderWords(){const day=current(),seen=day.words.filter((_,i)=>s().cardsSeen.includes(cardKey(i))).length,all=seen===day.words.length;lessonShell(`<p class="science-kicker">DAY ${day.day} · FIELD WORDS</p><h1>Vocabulary field kit</h1><p class="science-lead">Tap each card. Read the English meaning before using Translate.</p>${vi("Chạm vào từng thẻ. Hãy đọc nghĩa tiếng Anh trước khi dùng nút Dịch.")}<div class="science-flashcards compact">${day.words.map((word,i)=>{const opened=s().cardsSeen.includes(cardKey(i));return `<button class="science-flashcard ${opened?"seen":""}" data-card="${i}"><span class="word-icon">${day.icon}</span><strong>${word.en}</strong><small>${opened?`${word.meaning}${translated()?`<em>${word.vi}</em>`:""}`:"Tap to reveal"}</small></button>`}).join("")}</div><p class="science-note">${all?"Field kit ready!":`${seen}/${day.words.length} cards opened`}</p>`,nextButton("Use the evidence →"));document.querySelectorAll("[data-card]").forEach(card=>card.onclick=()=>{const item=cardKey(card.dataset.card);if(!s().cardsSeen.includes(item))s().cardsSeen.push(item);persist();render()});$("scienceNext").disabled=!all;$("scienceNext").onclick=()=>{s().questionIndex=0;go("lesson",2)}}
  function renderQuestion(){const day=current(),guide=day.guide||"Nilo",q=day.questions[s().questionIndex],aKey=answerKey(),answer=s().answers[aKey],good=s().feedback.startsWith("Correct");lessonShell(`<p class="science-kicker">DAY ${day.day} · THINK LIKE A SCIENTIST · ${s().questionIndex+1}/${day.questions.length}</p><h1>${esc(q.prompt)}</h1>${vi(q.vi)}<div class="science-choices">${q.choices.map((choice,i)=>`<button data-choice="${i}" class="${answer===i?"selected":""}"><span>${String.fromCharCode(65+i)}</span>${esc(choice)}</button>`).join("")}</div><p class="science-feedback ${good?"good":""}">${esc(s().feedback)}</p>${s().hintDepth?`<div class="science-hint"><strong>${s().hintDepth===1?guide+"'s clue":"Deeper clue"}</strong><p>${esc(s().hintDepth===1?q.hint1:q.hint2)}</p></div>`:""}`,`<button class="science-secondary" id="scienceHint">${s().hintDepth===0?"Hint 1 · Free":s().hintDepth===1?(ctx.state.human.shield?"Deeper hint · −1 Shield":"🔒 Deeper hint · Need 1 Shield"):"Hint opened"}</button>${good?nextButton(s().questionIndex===day.questions.length-1?(day.day===5?"Find the final sample →":"Complete Day "+day.day+" →"):"Next question →"):""}`);document.querySelectorAll("[data-choice]").forEach(button=>button.onclick=()=>{const chosen=Number(button.dataset.choice);s().answers[aKey]=chosen;s().feedback=chosen===q.right?`Correct! ${q.why}`:"Not yet. Nothing was lost—use the evidence and try again.";persist();render()});$("scienceHint").onclick=()=>{if(s().hintDepth===0)s().hintDepth=1;else if(s().hintDepth===1&&ctx.state.human.shield>0){ctx.state.human.shield--;s().hintDepth=2}persist();render()};if($("scienceNext"))$("scienceNext").onclick=()=>{if(s().questionIndex<day.questions.length-1){s().questionIndex++;s().feedback="";s().hintDepth=0;persist();render()}else if(day.day===5)go("lesson",3);else finishDay()}}
  function renderSearch(){const w=activeWeek(),searches={1:{core:"Wetland Core",guide:"Nilo",clue:"Look below the dam where water is flowing.",className:""},2:{core:"Seed Voyager Core",guide:"Mira",clue:"Look near the new sprout in the soil.",className:"seed-search"},3:{core:"Pollinator Network Core",guide:"Kiko",clue:"Look near the honeycomb in the observation hive.",className:"bee-search"},4:{core:"Winter Survival Core",guide:"Tova",clue:"Look beside the squirrel's winter food cache.",className:"winter-search"}},search=searches[w.number]||searches[1];lessonShell(`<p class="science-kicker">DAY 5 · HIDDEN DISCOVERY</p><h1>Recover the ${search.core}</h1><p class="science-lead">${search.guide}'s scanner found a final sample in the field. Search the scene and collect it for the Earth Lab.</p>${vi(`${search.guide} đã phát hiện một mẫu vật cuối cùng ngoài thực địa. Hãy tìm trong bức hình và thu thập nó cho Phòng thí nghiệm Trái Đất.`)}<div class="science-search-scene ${search.className} ${s().hiddenFound?"found":""}"><img src="${current().image}" alt="Search the scene for the hidden ${search.core}"><button id="scienceCore" aria-label="Hidden ${search.core}"><i>◆</i></button>${s().hiddenFound?`<div class="sample-found"><span>💎</span><strong>${search.core} found!</strong><small>Five days of evidence are now connected.</small></div>`:""}</div><p class="science-note">${s().hiddenFound?"Final sample secured.":search.clue}</p>`,s().hiddenFound?nextButton(`Complete Week ${w.number} →`):"");$("scienceCore").onclick=()=>{s().hiddenFound=true;persist();render()};if($("scienceNext"))$("scienceNext").onclick=finishDay}
  function finishDay(){const day=current(),list=doneDays();if(!list.includes(day.day))list.push(day.day);list.sort((a,b)=>a-b);if(!s().discoveries.includes(day.reward))s().discoveries.push(day.reward);if(!ctx.state.inventory.includes(day.reward))ctx.state.inventory.push(day.reward);if(day.day===5&&!ctx.state.inventory.includes("Knowledge Crystal"))ctx.state.inventory.push("Knowledge Crystal");s().stage=day.day===5?4:3;persist();render()}
  function renderComplete(){const day=current(),w=activeWeek(),weekDone=doneDays().length===5,isFinalDay=day.day===5,totalDays=Object.keys(weeks).length*5;lessonShell(`<div class="science-complete"><div class="upgrade-burst" aria-hidden="true">${day.rewardIcon}</div><p class="science-kicker">${weekDone?`WEEK ${w.number} COMPLETE`:"DAY "+day.day+" COMPLETE"}</p><h1>${weekDone?"Field report transmitted!":isFinalDay?"Final report drafted!":"Earth Lab upgraded!"}</h1><p>${weekDone?`You connected all five investigations in ${w.subtitle} into one scientific explanation.`:isFinalDay?`The final report is ready. Complete the remaining field days to transmit the full Week ${w.number} report.`:`Evidence from ${day.short} has been stored in the Earth Lab.`}</p><div class="science-rewards"><span>${day.rewardIcon}<b>${day.reward}</b></span><span>💎<b>Knowledge Crystal ${doneDays().length}/5</b></span><span>🔬<b>Lab Level ${s().labLevel}/${totalDays}</b></span></div><div class="lab-upgrade"><img src="${w.hero}" alt="Earth Discovery Lab upgraded after Day ${day.day}"><i style="--upgrade:${Math.min(100,s().labLevel/totalDays*100)}%"></i></div>${weekDone?`<p class="week-finished">🏆 Week ${w.number} collection complete: ${w.days.slice(1).map(item=>item.reward).join(" · ")}</p>`:""}</div>`,`<button class="science-secondary" id="scienceReplay">Review Day ${day.day}</button><button class="science-primary" id="scienceFinish">Week overview →</button>`);$("scienceReplay").onclick=()=>startDay(day.day);$("scienceFinish").onclick=()=>go("week")}
  function vocabularyEntries(weekNumber){return weeks[weekNumber].days.slice(1).flatMap(day=>day.words.map((word,index)=>({week:weekNumber,day:day.day,index,key:`${weekNumber}-${day.day}-${index}`,word,image:day.vocabImage,title:day.short,position:["left","center","right"][index]})))}
  function openVocabularyHologram(key){const entry=Object.values(weeks).flatMap(w=>vocabularyEntries(w.number)).find(item=>item.key===key);if(!entry)return;const remembered=s().vocabularyNotes.includes(key),layer=document.createElement("div");layer.className="vocab-hologram";layer.id="vocabHologram";layer.setAttribute("role","dialog");layer.setAttribute("aria-modal","true");layer.innerHTML=`<div class="holo-rings" aria-hidden="true"><i></i><i></i><i></i></div><article class="holo-panel"><button class="holo-close" id="holoClose" aria-label="Close vocabulary hologram">×</button><p class="science-kicker">WEEK ${entry.week} · DAY ${entry.day} · ${esc(entry.title)}</p><div class="holo-specimen" style="--word-image:url('${entry.image}');--word-position:${entry.position}"></div><small>FIELD VOCABULARY RECORD</small><h2>${esc(entry.word.en)}</h2><p class="holo-definition">${esc(entry.word.meaning)}</p><p class="holo-translation"><b>VI</b> ${esc(entry.word.vi)}</p><button class="holo-remember ${remembered?"saved":""}" id="holoRemember">${remembered?"★ Added to words to remember":"☆ Mark this word to remember"}</button></article>`;document.body.appendChild(layer);$("holoClose").onclick=()=>layer.remove();layer.onclick=event=>{if(event.target===layer)layer.remove()};$("holoRemember").onclick=()=>{const list=s().vocabularyNotes,index=list.indexOf(key);if(index>=0)list.splice(index,1);else list.push(key);persist();layer.remove();renderJournal();openVocabularyHologram(key)}}
  function renderJournal(){const remembered=s().vocabularyNotes||[],totalWords=Object.values(weeks).reduce((sum,w)=>sum+vocabularyEntries(w.number).length,0);ctx.view.scrollTop=0;ctx.view.innerHTML=`<section class="science-journal-screen"><header class="journal-hero"><button class="journal-back" id="journalBack">← Planet Earth</button><div><p class="science-kicker">EARTH ARCHIVE · SCIENTIST'S FIELD BOOK</p><h1>Vocabulary<br><span>Journal</span></h1><p>Open a specimen card to project its English meaning and Vietnamese translation as a hologram.</p><div class="journal-stats"><b>${totalWords} illustrated words</b><b>${remembered.length} marked to remember</b></div></div></header><div class="journal-ledger">${Object.values(weeks).map(w=>{const entries=vocabularyEntries(w.number);return `<section class="journal-week"><div class="journal-week-heading"><div><small>COLLECTION ${String(w.number).padStart(2,"0")}</small><h2>Week ${w.number} · ${esc(w.title)}</h2><p>${esc(w.subtitle)} · ${entries.length} field words</p></div><span>${remembered.filter(key=>key.startsWith(w.number+"-")).length}/${entries.length} marked</span></div><div class="journal-word-grid">${entries.map((entry,index)=>`<button class="journal-word ${remembered.includes(entry.key)?"remembered":""}" data-vocab-key="${entry.key}" aria-label="Reveal field word ${index+1} from Week ${w.number}"><span class="journal-thumb" style="--word-image:url('${entry.image}');--word-position:${entry.position}"></span><i>DAY ${entry.day} · SPECIMEN ${String(index+1).padStart(2,"0")}</i><strong>${remembered.includes(entry.key)?"★ Marked to remember":"Tap to reveal hologram"}</strong></button>`).join("")}</div></section>`}).join("")}</div></section>`;$("journalBack").onclick=ctx.openEarth;document.querySelectorAll("[data-vocab-key]").forEach(button=>button.onclick=()=>openVocabularyHologram(button.dataset.vocabKey))}
  function renderLesson(){const day=current();if(s().stage===0)renderStory();else if(s().stage===1)renderWords();else if(s().stage===2)renderQuestion();else if(day.day===5&&s().stage===3)renderSearch();else renderComplete()}
  function decorateLessonVisuals(){if(s().view!=="lesson")return;const day=current();if(s().stage===1)document.querySelectorAll(".word-icon").forEach((node,index)=>{node.textContent="";node.className="word-photo";node.style.setProperty("--word-image",`url('${day.vocabImage}')`);node.style.setProperty("--word-position",["left","center","right"][index])});if(s().stage===2){const card=document.querySelector(".science-lesson-card");if(card){card.classList.add("question-visual-card");card.style.setProperty("--question-image",`url('${day.image}')`)}}if(day.day===5&&s().stage===3){const search=document.querySelector(".science-search-scene>img");if(search)search.src=day.image}const rewardCards=document.querySelectorAll(".science-rewards>span");if(rewardCards.length){const images=[day.image,"assets/science-knowledge-crystal-v2.png","assets/science-earth-lab-thumb-v2.png"];rewardCards.forEach((card,index)=>{[...card.childNodes].filter(node=>node.nodeType===3).forEach(node=>node.remove());const img=document.createElement("img");img.src=images[index];img.alt="";card.prepend(img)});const burst=document.querySelector(".upgrade-burst");if(burst)burst.innerHTML=`<img src="${day.image}" alt="">`}}
  function render(){if(!ctx)return;normalizeState();if(s().view==="lesson")renderLesson();else if(s().view==="week")renderWeek();else if(s().view==="journal")renderJournal();else renderLab();decorateLessonVisuals()}
  window.ScienceDiscovery={render(context){ctx=context;render()}};
})();
